sp_widget.client_script:
api.controller = function($scope) {

    var c = this;


    /* ==========================================
       PAGE
       ========================================== */

    c.currentPage =
        'overview';


    /* ==========================================
       RECORD FORM
       ========================================== */

    c.showRecordForm =
        false;

    c.selectedRecord =
        null;

    c.savingRecord =
        false;

    c.formError =
        '';

    c.formSuccess =
        '';

    c.notesVisible =
        false;

    c.notesRequired =
        false;


    /* ==========================================
       FILTER OPTIONS
       ========================================== */

    c.useCaseOptions =
        c.data.filterOptions &&
        c.data.filterOptions.useCases
            ? c.data.filterOptions.useCases
            : [];

    c.priorityOptions =
        c.data.filterOptions &&
        c.data.filterOptions.priorities
            ? c.data.filterOptions.priorities
            : [];


    c.assignmentFilters = {

        use_case:
            '',

        current_priority:
            ''
    };


    c.filteredAssignmentIds =
        angular.copy(
            c.data.myAssignmentIds || []
        );


    /* ==========================================
       CHANGE PAGE
       ========================================== */

    c.changePage = function(page) {

        c.currentPage =
            page;

        c.closeRecordForm();
    };


    /* ==========================================
       FILTER ASSIGNED TASKS
       ========================================== */

    c.applyAssignmentFilters =
        function() {

            var filtered = [];

            var ids =
                c.data.myAssignmentIds ||
                [];

            var selectedUseCase =
                String(
                    c.assignmentFilters.use_case ||
                    ''
                ).trim();

            var selectedPriority =
                String(
                    c.assignmentFilters.current_priority ||
                    ''
                ).trim();


            for (
                var i = 0;
                i < ids.length;
                i++
            ) {

                var sysId =
                    ids[i];

                var record =
                    c.data.records[
                        sysId
                    ];


                if (!record) {

                    continue;
                }


                /* --------------------------------
                   Use Case
                   -------------------------------- */

                var useCaseMatch =
                    true;

                if (
                    selectedUseCase !== ''
                ) {

                    var recordUseCase =
                        String(
                            record.use_case ||
                            ''
                        ).trim();

                    var recordUseCaseDisplay =
                        String(
                            record.use_case_display ||
                            ''
                        ).trim();


                    useCaseMatch =
                        recordUseCase ===
                            selectedUseCase ||
                        recordUseCaseDisplay ===
                            selectedUseCase;
                }


                /* --------------------------------
                   Priority
                   -------------------------------- */

                var priorityMatch =
                    true;

                if (
                    selectedPriority !== ''
                ) {

                    var recordPriority =
                        String(
                            record.current_priority ||
                            ''
                        ).trim();

                    var recordPriorityDisplay =
                        String(
                            record.current_priority_display ||
                            ''
                        ).trim();


                    priorityMatch =
                        recordPriority ===
                            selectedPriority ||
                        recordPriorityDisplay ===
                            selectedPriority;
                }


                if (
                    useCaseMatch &&
                    priorityMatch
                ) {

                    filtered.push(
                        sysId
                    );
                }
            }


            c.filteredAssignmentIds =
                filtered;
        };


    /* ==========================================
       CLEAR FILTERS
       ========================================== */

    c.clearAssignmentFilters =
        function() {

            c.assignmentFilters.use_case =
                '';

            c.assignmentFilters.current_priority =
                '';

            c.filteredAssignmentIds =
                angular.copy(
                    c.data.myAssignmentIds ||
                    []
                );
        };


    /* ==========================================
       OPEN RECORD
       ========================================== */

    c.openRecord =
        function(sysId) {

            c.formError =
                '';

            c.formSuccess =
                '';

            c.selectedRecord =
                null;


            var record =
                c.data.records[
                    sysId
                ];


            if (!record) {

                c.formError =
                    'The selected task could not be found.';

                return;
            }


            c.selectedRecord =
                angular.copy(
                    record
                );


            if (
                !c.selectedRecord.approval
            ) {

                c.selectedRecord.approval =
                    'requested';
            }


            c.selectedRecord.approval =
                String(
                    c.selectedRecord.approval
                ).toLowerCase();


            c.updateNotesVisibility();

            c.showRecordForm =
                true;
        };


    /* ==========================================
       ACCEPT BUTTON
       ========================================== */

    c.acceptRecord =
        function(sysId) {

            c.formError =
                '';

            c.formSuccess =
                '';


            var record =
                c.data.records[
                    sysId
                ];


            if (!record) {

                c.formError =
                    'The selected task could not be found.';

                return;
            }


            c.selectedRecord =
                angular.copy(
                    record
                );


            c.selectedRecord.approval =
                'approved';


            c.updateNotesVisibility();

            c.showRecordForm =
                true;
        };


    /* ==========================================
       CLOSE FORM
       ========================================== */

    c.closeRecordForm =
        function() {

            c.showRecordForm =
                false;

            c.selectedRecord =
                null;

            c.formError =
                '';

            c.formSuccess =
                '';

            c.savingRecord =
                false;

            c.notesVisible =
                false;

            c.notesRequired =
                false;
        };


    /* ==========================================
       NOTES VISIBILITY
       ========================================== */

    c.updateNotesVisibility =
        function() {

            if (!c.selectedRecord) {

                c.notesVisible =
                    false;

                c.notesRequired =
                    false;

                return;
            }


            var approval =
                String(
                    c.selectedRecord.approval ||
                    ''
                ).toLowerCase();


            if (
                approval === 'requested'
            ) {

                c.notesVisible =
                    false;

                c.notesRequired =
                    false;

            } else {

                /*
                 * Approved and Rejected
                 * both require notes.
                 */

                c.notesVisible =
                    true;

                c.notesRequired =
                    true;
            }
        };


    /* ==========================================
       SAVE RECORD
       ========================================== */

    c.saveRecord =
        function() {

            c.formError =
                '';

            c.formSuccess =
                '';


            if (
                !c.selectedRecord ||
                !c.selectedRecord.sys_id
            ) {

                c.formError =
                    'No task selected.';

                return;
            }


            var approval =
                String(
                    c.selectedRecord.approval ||
                    ''
                ).toLowerCase();


            var notes =
                String(
                    c.selectedRecord.notes ||
                    ''
                );


            if (
                approval !== 'requested' &&
                approval !== 'approved' &&
                approval !== 'rejected'
            ) {

                c.formError =
                    'Please select a valid approval status.';

                return;
            }


            /*
             * Notes mandatory for
             * Approved and Rejected.
             */

            if (
                (
                    approval === 'approved' ||
                    approval === 'rejected'
                ) &&
                notes.trim() === ''
            ) {

                c.formError =
                    'Notes are required when the approval is Approved or Rejected.';

                return;
            }


            c.savingRecord =
                true;


            c.server.get({

                action:
                    'saveRecord',

                sys_id:
                    c.selectedRecord.sys_id,

                approval:
                    approval,

                notes:
                    notes

            }).then(

                function(response) {

                    if (
                        response.data &&
                        response.data.saveError
                    ) {

                        c.formError =
                            response.data.saveError;

                        c.savingRecord =
                            false;

                        return;
                    }


                    if (
                        response.data
                    ) {

                        angular.extend(
                            c.data,
                            response.data
                        );
                    }


                    c.useCaseOptions =
                        c.data.filterOptions &&
                        c.data.filterOptions.useCases
                            ? c.data.filterOptions.useCases
                            : [];


                    c.priorityOptions =
                        c.data.filterOptions &&
                        c.data.filterOptions.priorities
                            ? c.data.filterOptions.priorities
                            : [];


                    c.filteredAssignmentIds =
                        angular.copy(
                            c.data.myAssignmentIds ||
                            []
                        );


                    c.applyAssignmentFilters();


                    if (
                        response.data &&
                        response.data.saveSuccess
                    ) {

                        c.formSuccess =
                            'Task updated successfully.';

                        setTimeout(
                            function() {

                                $scope.$apply(
                                    function() {

                                        c.closeRecordForm();

                                    }
                                );

                            },
                            700
                        );
                    }


                    c.savingRecord =
                        false;
                },


                function() {

                    c.formError =
                        'Unable to update the task. Please try again.';

                    c.savingRecord =
                        false;
                }
            );
        };


    /* ==========================================
       REPORT BAR WIDTH
       ========================================== */

    c.getBarWidth =
        function(value, list) {

            var current =
                parseInt(
                    value,
                    10
                ) || 0;

            var maximum =
                0;


            if (
                list &&
                list.length
            ) {

                for (
                    var i = 0;
                    i < list.length;
                    i++
                ) {

                    var count =
                        parseInt(
                            list[i].count,
                            10
                        ) || 0;


                    if (
                        count > maximum
                    ) {

                        maximum =
                            count;
                    }
                }
            }


            if (
                maximum === 0
            ) {

                return '0%';
            }


            return (
                (
                    current /
                    maximum
                ) * 100
            ) + '%';
        };


    /* ==========================================
       HORIZONTAL TABLE DRAG
       ========================================== */

    setTimeout(
        function() {

            var adminTable =
                document.getElementById(
                    'adminAssignmentScroll'
                );


            if (!adminTable) {

                return;
            }


            var dragging =
                false;

            var startX =
                0;

            var startScroll =
                0;


            adminTable.addEventListener(
                'mousedown',
                function(event) {

                    dragging =
                        true;

                    startX =
                        event.pageX -
                        adminTable.offsetLeft;

                    startScroll =
                        adminTable.scrollLeft;
                }
            );


            adminTable.addEventListener(
                'mouseleave',
                function() {

                    dragging =
                        false;
                }
            );


            adminTable.addEventListener(
                'mouseup',
                function() {

                    dragging =
                        false;
                }
            );


            adminTable.addEventListener(
                'mousemove',
                function(event) {

                    if (!dragging) {

                        return;
                    }


                    event.preventDefault();


                    var x =
                        event.pageX -
                        adminTable.offsetLeft;


                    var distance =
                        (
                            x -
                            startX
                        ) * 1.2;


                    adminTable.scrollLeft =
                        startScroll -
                        distance;
                }
            );

        },
        500
    );

};

sp_widget.css:
/* ==========================================
   ADMIN DASHBOARD
   ========================================== */

.admin-dashboard {
    display: flex;
    min-height: 100vh;
    background: #f5f7f8;
    color: #243238;
    font-family: Arial, Helvetica, sans-serif;
}


/* ==========================================
   SIDEBAR
   ========================================== */

.admin-sidebar {
    width: 240px;
    min-width: 240px;
    background: #1E293B;
    border-right: 1px solid #334155;
    padding: 22px 16px;
    box-sizing: border-box;
}

.admin-brand {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 6px 8px 26px;
}

.admin-brand-icon {
    width: 38px;
    height: 38px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #2563EB;
    color: #FFFFFF;
    font-size: 18px;
    font-weight: 700;
    border: 2px solid #60A5FA;
    box-shadow: 0 5px 12px rgba(37, 99, 235, 0.30);
}

.admin-brand-title {
    font-size: 16px;
    font-weight: 700;
    color: #FFFFFF;
}

.admin-brand-subtitle {
    margin-top: 3px;
    font-size: 12px;
    color: #94A3B8;
}

.admin-navigation {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.admin-nav-item {
    width: 100%;
    min-height: 44px;
    padding: 0 13px;
    border: 0;
    border-radius: 8px;
    background: transparent;
    color: #CBD5E1;
    display: flex;
    align-items: center;
    gap: 12px;
    text-align: left;
    cursor: pointer;
    font-size: 14px;
}

.admin-nav-item:hover {
    background: #334155;
    color: #FFFFFF;
}

.admin-nav-item.active {
    background: #2563EB;
    color: #FFFFFF;
    font-weight: 600;
}

.admin-nav-icon {
    width: 20px;
    text-align: center;
    font-size: 17px;
}


/* ==========================================
   CONTENT
   ========================================== */

.admin-content {
    flex: 1;
    min-width: 0;
    padding: 30px;
    overflow-x: hidden;
}

.admin-page {
    width: 100%;
}

.admin-page-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 24px;
}

.admin-page-header h1 {
    margin: 0;
    font-size: 27px;
    color: #123c3a;
}

.admin-page-header p {
    margin: 7px 0 0;
    color: #6d7977;
    font-size: 14px;
}


/* ==========================================
   KPI
   ========================================== */

.admin-kpi-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
    margin-bottom: 22px;
}

.admin-kpi-card {
    background: #ffffff;
    border: 1px solid #dfe5e7;
    border-radius: 12px;
    padding: 21px;
    box-sizing: border-box;
}

.admin-kpi-label {
    font-size: 13px;
    color: #697674;
    font-weight: 600;
}

.admin-kpi-value {
    margin-top: 8px;
    font-size: 30px;
    font-weight: 700;
    color: #123c3a;
}

.admin-kpi-caption {
    margin-top: 5px;
    font-size: 12px;
    color: #8a9492;
}


/* ==========================================
   SECTION CARD
   ========================================== */

.admin-section-card {
    background: #ffffff;
    border: 1px solid #dfe5e7;
    border-radius: 12px;
    overflow: hidden;
    margin-bottom: 22px;
}

.admin-section-header {
    padding: 19px 21px;
    border-bottom: 1px solid #e5e9ea;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 15px;
}

.admin-section-header h2 {
    margin: 0;
    font-size: 18px;
    color: #123c3a;
}

.admin-section-header p {
    margin: 5px 0 0;
    color: #7a8583;
    font-size: 13px;
}

.admin-link-button {
    border: 0;
    background: transparent;
    color: #123c3a;
    font-weight: 600;
    cursor: pointer;
}

.admin-link-button:hover {
    text-decoration: underline;
}


/* ==========================================
   FILTERS
   ========================================== */

.admin-filter-card {
    background: #ffffff;
    border: 1px solid #dfe5e7;
    border-radius: 12px;
    margin-bottom: 22px;
    padding: 20px;
}

.admin-filter-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 18px;
}

.admin-filter-header h3 {
    margin: 0;
    color: #123c3a;
    font-size: 16px;
}

.admin-filter-header span {
    display: block;
    margin-top: 4px;
    color: #7a8583;
    font-size: 12px;
}

.admin-filter-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(200px, 1fr));
    gap: 16px;
}

.admin-filter-field label,
.admin-form-field label {
    display: block;
    margin-bottom: 7px;
    font-size: 12px;
    font-weight: 600;
    color: #4d5a58;
}

.admin-select {
    width: 100%;
    height: 40px;
    padding: 0 11px;
    border: 1px solid #ccd5d3;
    border-radius: 7px;
    background: #ffffff;
    color: #273533;
    box-sizing: border-box;
}

.admin-select:focus {
    outline: none;
    border-color: #123c3a;
}

.admin-clear-button {
    border: 1px solid #ccd5d3;
    border-radius: 7px;
    background: #ffffff;
    padding: 8px 13px;
    color: #53615f;
    cursor: pointer;
}

.admin-clear-button:hover {
    background: #f3f6f5;
}


/* ==========================================
   TABLE
   ========================================== */

.admin-table-scroll {
    width: 100%;
    overflow-x: auto;
    overflow-y: hidden;
    cursor: grab;
}

.admin-table-scroll:active {
    cursor: grabbing;
}

.admin-wide-table {
    max-height: 650px;
    overflow: auto;
}

.admin-task-table {
    width: max-content;
    min-width: 100%;
    border-collapse: collapse;
    font-size: 13px;
}

.admin-task-table th {
    position: sticky;
    top: 0;
    z-index: 2;
    background: #f1f5f4;
    color: #43514f;
    font-size: 11px;
    font-weight: 700;
    text-align: left;
    white-space: nowrap;
    padding: 12px 13px;
    border-bottom: 1px solid #d9e0de;
}

.admin-task-table td {
    padding: 12px 13px;
    border-bottom: 1px solid #e7ebeb;
    color: #465350;
    vertical-align: top;
    max-width: 260px;
    line-height: 1.45;
}

.admin-task-table tbody tr:hover {
    background: #fafcfc;
}

.admin-action-cell {
    min-width: 150px;
    white-space: nowrap;
}

.admin-empty-cell {
    text-align: center !important;
    padding: 35px !important;
    color: #8a9593 !important;
}


/* ==========================================
   ACTION BUTTONS
   ========================================== */

.admin-open-button,
.admin-accept-button {
    border: 0;
    border-radius: 6px;
    padding: 7px 11px;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    margin-right: 5px;
}

.admin-open-button {
    background: #e8f0ed;
    color: #123c3a;
}

.admin-open-button:hover {
    background: #dce8e4;
}

.admin-accept-button {
    background: #123c3a;
    color: #ffffff;
}

.admin-accept-button:hover {
    opacity: 0.9;
}


/* ==========================================
   REPORTS
   ========================================== */

.admin-report-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
}

.admin-report-card {
    background: #ffffff;
    border: 1px solid #dfe5e7;
    border-radius: 12px;
    padding: 20px;
}

.admin-report-card h3 {
    margin: 0 0 18px;
    color: #123c3a;
    font-size: 16px;
}

.admin-report-row {
    display: grid;
    grid-template-columns: 160px 1fr 35px;
    align-items: center;
    gap: 10px;
    margin-bottom: 13px;
}

.admin-report-label {
    font-size: 12px;
    color: #53615f;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.admin-report-track {
    height: 8px;
    border-radius: 20px;
    background: #e9eeec;
    overflow: hidden;
}

.admin-report-bar {
    height: 100%;
    border-radius: 20px;
    background: #123c3a;
}

.admin-report-count {
    font-size: 12px;
    font-weight: 700;
    text-align: right;
    color: #123c3a;
}


/* ==========================================
   MODAL
   ========================================== */

.admin-modal-overlay {
    position: fixed;
    inset: 0;
    z-index: 1000;
    background: rgba(20, 31, 30, 0.55);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 25px;
    box-sizing: border-box;
}

.admin-modal {
    width: min(1050px, 100%);
    max-height: 92vh;
    background: #ffffff;
    border-radius: 14px;
    box-shadow: 0 18px 60px rgba(0, 0, 0, 0.18);
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.admin-modal-header {
    padding: 20px 24px;
    border-bottom: 1px solid #e1e7e5;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
}

.admin-modal-header h2 {
    margin: 0;
    color: #123c3a;
    font-size: 20px;
}

.admin-modal-header p {
    margin: 5px 0 0;
    color: #7a8583;
    font-size: 13px;
}

.admin-modal-close {
    width: 34px;
    height: 34px;
    border: 0;
    border-radius: 7px;
    background: #f2f5f4;
    color: #53615f;
    font-size: 22px;
    cursor: pointer;
}

.admin-modal-close:hover {
    background: #e8eeec;
}

.admin-modal-body {
    padding: 24px;
    overflow-y: auto;
}

.admin-form-section {
    margin-bottom: 25px;
}

.admin-form-section:last-child {
    margin-bottom: 0;
}

.admin-form-section-title {
    margin-bottom: 15px;
    padding-bottom: 9px;
    border-bottom: 1px solid #e5e9e8;
    color: #123c3a;
    font-size: 14px;
    font-weight: 700;
}

.admin-form-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 16px;
}

.admin-form-field {
    min-width: 0;
}

.admin-form-field input,
.admin-form-field textarea,
.admin-form-field select {
    width: 100%;
    box-sizing: border-box;
    border: 1px solid #ccd5d3;
    border-radius: 7px;
    background: #ffffff;
    color: #283633;
    font-size: 13px;
    padding: 10px 11px;
}

.admin-form-field input {
    height: 40px;
}

.admin-form-field textarea {
    min-height: 95px;
    resize: vertical;
    line-height: 1.5;
}

.admin-form-field input[readonly],
.admin-form-field textarea[readonly] {
    background: #f5f7f7;
    color: #5d6967;
}

.admin-form-field select:focus,
.admin-form-field textarea:focus {
    outline: none;
    border-color: #123c3a;
}

.admin-full-field {
    grid-column: 1 / -1;
}

.admin-approval-select {
    background: #ffffff;
    font-weight: 600;
}

.admin-notes {
    min-height: 120px !important;
}

.admin-required {
    color: #b52b2b;
    font-size: 14px;
}

.admin-field-help {
    display: block;
    margin-top: 6px;
    color: #7b8785;
    font-size: 11px;
}

.admin-modal-footer {
    padding: 16px 24px;
    border-top: 1px solid #e1e7e5;
    display: flex;
    justify-content: flex-end;
    gap: 10px;
}

.admin-cancel-button,
.admin-save-button {
    min-width: 110px;
    height: 40px;
    padding: 0 16px;
    border-radius: 7px;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
}

.admin-cancel-button {
    border: 1px solid #ccd5d3;
    background: #ffffff;
    color: #53615f;
}

.admin-cancel-button:hover {
    background: #f4f6f5;
}

.admin-save-button {
    border: 0;
    background: #123c3a;
    color: #ffffff;
}

.admin-save-button:hover {
    opacity: 0.92;
}

.admin-save-button:disabled,
.admin-cancel-button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}


/* ==========================================
   FORM MESSAGES
   ========================================== */

.admin-form-message {
    margin: 16px 24px 0;
    padding: 11px 13px;
    border-radius: 7px;
    font-size: 13px;
}

.admin-error {
    background: #fff1f1;
    border: 1px solid #efcccc;
    color: #a22c2c;
}

.admin-success {
    background: #eef8f2;
    border: 1px solid #cce5d5;
    color: #2f6f45;
}


/* ==========================================
   RESPONSIVE
   ========================================== */

@media (max-width: 900px) {

    .admin-sidebar {
        width: 200px;
        min-width: 200px;
    }

    .admin-content {
        padding: 20px;
    }

    .admin-kpi-grid {
        grid-template-columns: 1fr;
    }

    .admin-report-grid {
        grid-template-columns: 1fr;
    }

}


@media (max-width: 700px) {

    .admin-dashboard {
        flex-direction: column;
    }

    .admin-sidebar {
        width: 100%;
        min-width: 100%;
        border-right: 0;
        border-bottom: 1px solid #334155;
    }

    .admin-navigation {
        flex-direction: row;
        overflow-x: auto;
    }

    .admin-nav-item {
        min-width: max-content;
    }

    .admin-content {
        padding: 15px;
    }

    .admin-filter-grid,
    .admin-form-grid {
        grid-template-columns: 1fr;
    }

    .admin-full-field {
        grid-column: auto;
    }

    .admin-modal-overlay {
        padding: 10px;
    }

    .admin-modal {
        max-height: 96vh;
    }

}

sp_widget.script:
(function() {

    /* ==========================================
       DEFAULT DATA
       ========================================== */

    data.totalRequests = 0;
    data.pendingProblems = 0;
    data.resolvedRequests = 0;

    data.records = {};

    data.myAssignmentIds = [];
    data.recentAssignmentIds = [];
    data.historyIds = [];

    data.filterOptions = {
        useCases: [],
        priorities: []
    };

    data.reports = {
        useCase: [],
        priority: [],
        approval: [],
        overTime: []
    };

    data.saveSuccess = false;
    data.saveError = '';


    /* ==========================================
       TABLES / ADMIN GROUP
       ========================================== */

    var adminGroup =
        '1754d95bdd1f03107f44143a6accf85b';

    var taskTable =
        'x_snc_campus_foo_1_complain_tasks';

    var complaintTable =
        'x_snc_campus_foo_1_food_complaint';


    /* ==========================================
       SAVE EXISTING TASK
       ========================================== */

    if (
        input &&
        input.action === 'saveRecord' &&
        input.sys_id
    ) {

        var updateTask =
            new GlideRecord(taskTable);

        if (!updateTask.get(input.sys_id)) {

            data.saveError =
                'The selected task could not be found.';

        } else if (
            updateTask.getValue('assignment_group') !==
            adminGroup
        ) {

            data.saveError =
                'You are not allowed to update this task.';

        } else {

            var newApproval =
                String(
                    input.approval || ''
                ).toLowerCase();

            var newNotes =
                String(
                    input.notes || ''
                );


            /* ======================================
               VALIDATE APPROVAL
               ====================================== */

            if (
                newApproval !== 'requested' &&
                newApproval !== 'approved' &&
                newApproval !== 'rejected'
            ) {

                data.saveError =
                    'Please select a valid approval status.';

            }


            /* ======================================
               NOTES REQUIRED FOR APPROVED / REJECTED
               ====================================== */

            else if (
                (
                    newApproval === 'approved' ||
                    newApproval === 'rejected'
                ) &&
                newNotes.trim() === ''
            ) {

                data.saveError =
                    'Notes are required when the approval is Approved or Rejected.';

            }


            /* ======================================
               UPDATE RECORD

               ADMIN ONLY UPDATES:
               1. Approval
               2. Notes

               FLOW HANDLES:
               - Assignment Group
               - State
               - Active
               - Closed At
               - Closed By
               - Manager Assignment
               ====================================== */

            else {

                updateTask.setValue(
                    'approval',
                    newApproval
                );

                updateTask.setValue(
                    'notes',
                    newNotes
                );

                updateTask.update();

                data.saveSuccess = true;
            }
        }
    }


    /* ==========================================
       KPI - TOTAL REQUESTS
       ========================================== */

    var totalGA =
        new GlideAggregate(complaintTable);

    totalGA.addAggregate('COUNT');
    totalGA.query();

    if (totalGA.next()) {

        data.totalRequests =
            parseInt(
                totalGA.getAggregate('COUNT'),
                10
            ) || 0;
    }


    /* ==========================================
       KPI - RESOLVED REQUESTS
       ========================================== */

    var resolvedGA =
        new GlideAggregate(complaintTable);

    resolvedGA.addQuery(
        'state',
        'resolved'
    );

    resolvedGA.addAggregate('COUNT');
    resolvedGA.query();

    if (resolvedGA.next()) {

        data.resolvedRequests =
            parseInt(
                resolvedGA.getAggregate('COUNT'),
                10
            ) || 0;
    }


    /* ==========================================
       KPI - PENDING PROBLEMS
       ========================================== */

    var pendingGA =
        new GlideAggregate(taskTable);

    pendingGA.addQuery(
        'approval',
        'requested'
    );

    pendingGA.addAggregate('COUNT');
    pendingGA.query();

    if (pendingGA.next()) {

        data.pendingProblems =
            parseInt(
                pendingGA.getAggregate('COUNT'),
                10
            ) || 0;
    }


    /* ==========================================
       USE CASE FILTER OPTIONS
       ========================================== */

    var useCaseChoice =
        new GlideRecord('sys_choice');

    useCaseChoice.addQuery(
        'name',
        taskTable
    );

    useCaseChoice.addQuery(
        'element',
        'use_case'
    );

    useCaseChoice.addQuery(
        'inactive',
        false
    );

    useCaseChoice.orderBy('sequence');
    useCaseChoice.query();

    while (useCaseChoice.next()) {

        data.filterOptions.useCases.push({

            value:
                useCaseChoice.getValue('value'),

            label:
                useCaseChoice.getValue('label')
        });
    }


    /* ==========================================
       PRIORITY FILTER OPTIONS
       ========================================== */

    var priorityChoice =
        new GlideRecord('sys_choice');

    priorityChoice.addQuery(
        'name',
        taskTable
    );

    priorityChoice.addQuery(
        'element',
        'current_priority'
    );

    priorityChoice.addQuery(
        'inactive',
        false
    );

    priorityChoice.orderBy('sequence');
    priorityChoice.query();

    while (priorityChoice.next()) {

        data.filterOptions.priorities.push({

            value:
                priorityChoice.getValue('value'),

            label:
                priorityChoice.getValue('label')
        });
    }


    /* ==========================================
       LOAD TASK RECORDS
       ========================================== */

    var taskGR =
        new GlideRecord(taskTable);

    taskGR.orderByDesc('sys_created_on');
    taskGR.query();

    while (taskGR.next()) {

        var sysId =
            taskGR.getUniqueValue();


        /* --------------------------------------
           Safe field helper
           -------------------------------------- */

        function getValue(fieldName) {

            if (
                taskGR.isValidField(fieldName)
            ) {

                return taskGR.getValue(
                    fieldName
                ) || '';

            }

            return '';
        }


        function getDisplay(fieldName) {

            if (
                taskGR.isValidField(fieldName)
            ) {

                return taskGR.getDisplayValue(
                    fieldName
                ) || '';

            }

            return '';
        }


        /* --------------------------------------
           Store record
           -------------------------------------- */

        data.records[sysId] = {

            sys_id:
                sysId,

            number:
                getValue('number'),

            use_case:
                getValue('use_case'),

            use_case_display:
                getDisplay('use_case'),

            current_priority:
                getValue('current_priority'),

            current_priority_display:
                getDisplay('current_priority'),

            student_count:
                parseInt(
                    getValue('student_count'),
                    10
                ) || 0,

            state:
                getValue('state'),

            state_display:
                getDisplay('state'),

            assignment_group:
                getValue('assignment_group'),

            assignment_group_display:
                getDisplay('assignment_group'),

            problem_type:
                getValue('problem_type'),

            problem_type_display:
                getDisplay('problem_type'),

            short_description:
                getValue('short_description'),

            approval:
                getValue('approval'),

            approval_display:
                getDisplay('approval'),

            use_case_number:
                getValue('use_case_number'),

            mess_hall:
                getValue('mess_hall'),

            mess_hall_display:
                getDisplay('mess_hall'),

            meal_type:
                getValue('meal_type'),

            meal_type_display:
                getDisplay('meal_type'),

            priority_reason:
                getValue('priority_reason'),

            recomended_actions:
                getValue('recomended_actions'),

            resolution_status:
                getValue('resolution_status'),

            resolution_status_display:
                getDisplay('resolution_status'),

            notes:
                getValue('notes'),

            updated:
                getValue('sys_updated_on'),

            updated_display:
                getDisplay('sys_updated_on')
        };


        /* ======================================
           ASSIGNED TASKS
           ====================================== */

        if (
            getValue('assignment_group') ===
                adminGroup &&
            getValue('approval') ===
                'requested'
        ) {

            data.myAssignmentIds.push(
                sysId
            );
        }


        /* ======================================
           TASK HISTORY
           ====================================== */

        if (
            getValue('assignment_group') ===
                adminGroup &&
            (
                getValue('approval') ===
                    'approved' ||
                getValue('approval') ===
                    'rejected'
            )
        ) {

            data.historyIds.push(
                sysId
            );
        }
    }


    /* ==========================================
       RECENT ASSIGNED TASKS
       ========================================== */

    for (
        var recentIndex = 0;
        recentIndex <
            data.myAssignmentIds.length &&
        recentIndex < 5;
        recentIndex++
    ) {

        data.recentAssignmentIds.push(
            data.myAssignmentIds[
                recentIndex
            ]
        );
    }


    /* ==========================================
       REPORT - USE CASE
       ========================================== */

    var useCaseReport =
        new GlideAggregate(taskTable);

    useCaseReport.addAggregate(
        'COUNT'
    );

    useCaseReport.groupBy(
        'use_case'
    );

    useCaseReport.query();

    while (useCaseReport.next()) {

        data.reports.useCase.push({

            value:
                useCaseReport.getValue(
                    'use_case'
                ),

            label:
                useCaseReport.getDisplayValue(
                    'use_case'
                ) || 'Not specified',

            count:
                parseInt(
                    useCaseReport.getAggregate(
                        'COUNT'
                    ),
                    10
                ) || 0
        });
    }


    /* ==========================================
       REPORT - PRIORITY
       ========================================== */

    var priorityReport =
        new GlideAggregate(taskTable);

    priorityReport.addAggregate(
        'COUNT'
    );

    priorityReport.groupBy(
        'current_priority'
    );

    priorityReport.query();

    while (priorityReport.next()) {

        data.reports.priority.push({

            value:
                priorityReport.getValue(
                    'current_priority'
                ),

            label:
                priorityReport.getDisplayValue(
                    'current_priority'
                ) || 'Not specified',

            count:
                parseInt(
                    priorityReport.getAggregate(
                        'COUNT'
                    ),
                    10
                ) || 0
        });
    }


    /* ==========================================
       REPORT - APPROVAL
       ========================================== */

    var approvalReport =
        new GlideAggregate(taskTable);

    approvalReport.addAggregate(
        'COUNT'
    );

    approvalReport.groupBy(
        'approval'
    );

    approvalReport.query();

    while (approvalReport.next()) {

        data.reports.approval.push({

            value:
                approvalReport.getValue(
                    'approval'
                ),

            label:
                approvalReport.getDisplayValue(
                    'approval'
                ) || 'Not specified',

            count:
                parseInt(
                    approvalReport.getAggregate(
                        'COUNT'
                    ),
                    10
                ) || 0
        });
    }


    /* ==========================================
       REPORT - OVER TIME
       ========================================== */

    var timeReport =
        new GlideAggregate(taskTable);

    timeReport.addAggregate(
        'COUNT'
    );

    timeReport.addTrend(
        'sys_created_on',
        'month'
    );

    timeReport.query();

    while (timeReport.next()) {

        data.reports.overTime.push({

            label:
                timeReport.getValue(
                    'timeref'
                ),

            count:
                parseInt(
                    timeReport.getAggregate(
                        'COUNT'
                    ),
                    10
                ) || 0
        });
    }

})();
